-- PT109-S3-Q10. Batch 07.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch07$PT109-S3-Q10$batch07$ AND q.stimulus=$batch07$The importance of the ozone layer to terrestrial animals is that it entirely filters out some wavelengths of light but lets others through. Holes in the ozone layer and the dangers associated with these holes are well documented. However, one danger that has not been given sufficient attention is that these holes could lead to severe eye damage for animals of many species.$batch07$ AND q.prompt=$batch07$Which one of the following is most strongly supported by the statements above, if they are true?$batch07$ AND q.correct_choice=$batch07$E$batch07$) THEN RAISE EXCEPTION 'Question changed: PT109-S3-Q10'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch07$PT109-S3-Q10$batch07$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT109-S3-Q10'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch07$PT109-S3-Q10$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch07$Statements$batch07$, $batch07$The ozone layer matters because it completely filters out some wavelengths of light and lets others through. Holes in the ozone layer are dangerous. One danger that gets too little attention: the holes could cause severe eye damage in many species.$batch07$), (1, $batch07$Evaluate$batch07$, $batch07$Pause and infer. Why would a hole cause eye damage? Because the ozone blocks some wavelengths, and a hole lets them through. So some of the blocked wavelengths must be ones that can damage eyes, and they reach the ground more easily where there are holes.$batch07$), (2, $batch07$Goal$batch07$, $batch07$Some eye-damaging wavelengths get through more where there are holes.$batch07$)) v(position,label,body) WHERE q.qid=$batch07$PT109-S3-Q10$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch07$A$batch07$, $batch07$The ozone layer lets some wavelengths through. Some of those could damage eyes too. We only know that *some* damaging wavelengths are blocked, not all of them.$batch07$), ($batch07$B$batch07$, $batch07$The passage says nothing about where species live or how much of the earth the holes threaten.$batch07$), ($batch07$C$batch07$, $batch07$This is the most popular wrong answer. "Many species" could be hurt, but that doesn't tell us the rest are immune. Many is not all, and it is not "all but some" either.$batch07$), ($batch07$D$batch07$, $batch07$Nothing tells us a *single* wavelength can do the damage, or that *most* species are at risk.$batch07$), ($batch07$E$batch07$, $batch07$The ozone filters some wavelengths, and holes could cause eye damage. So some damaging wavelengths reach the surface more where the ozone is missing. "Some" and "more likely" keep it modest.$batch07$)) v(letter,body) WHERE q.qid=$batch07$PT109-S3-Q10$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
